131|         free(L->buf); free(L->tpbuf);
132|         L->buf = NULL; L->tpbuf = NULL;
133|         return -1;
134|     }
135|     L->atk = 1.0f - expf(-1.0f / (atk_ms * 0.001f * (float)fs));
136|     L->rel = 1.0f - expf(-1.0f / (rel_ms * 0.001f * (float)fs));
137|     L->gain = 1.0f;
138|     L->gain_min = 1.0f;
139|     return 0;
140| }
141| 
142| static void tp_limiter_free(tp_limiter_t *L)
143| {
144|     free(L->buf);
145|     free(L->tpbuf);
146|     L->buf = NULL;
147|     L->tpbuf = NULL;
148| }
149| 
150| /* 前进一步：输入样本 x，返回延迟 look 后、施加增益的样本。
151|  * 窗口峰值扫描的是各延迟位置上的"真峰值"（过采样后 4 点最大 |·|），
152|  * 因为乘上增益后各过采样点同乘 g，样本间峰同样被压到 ceiling 之下。 */
153| static float tp_limiter_step(tp_limiter_t *L, float x)
154| {
155|     double peak = 0.0;
156|     float need, c, y;
157|     int i, rd;
158| 
159|     L->buf[L->pos] = x;
160|     L->tpbuf[L->pos] = tp_oversample_peak(L->hist, (double)x);
161| 
162|     /* 更新 FIR 历史（在读取窗口之前，使当前样本参与其自身的过采样） */
163|     memmove(L->hist + 1, L->hist, 10 * sizeof(double));
164|     L->hist[0] = (double)x;
165| 
166|     for (i = 0; i < L->size; i++) {
167|         double v = L->tpbuf[i];
168|         if (v > peak) peak = v;
169|     }
170| 
171|     need = (peak > L->ceiling) ? (float)(L->ceiling / peak) : 1.0f;
172|     c = (need < L->gain) ? L->atk : L->rel;      /* 降增益快，回升慢 */
173|     L->gain += c * (need - L->gain);
174| 
175|     rd = (L->pos + 1) % L->size;                 /* 最老的样本 = 延迟 look 的那个 */
176|     y = L->buf[rd] * L->gain;
177|     L->pos = rd;
178| 
179|     if (L->gain < 0.999f) L->active++;
180|     L->gain_sum += (double)L->gain;
181|     if (L->gain < L->gain_min) L->gain_min = L->gain;
182| 
183|     /* 安全钳位兜底：限制最终样本幅度（平滑残差与 FIR 欠读兜底） */
184|     if (fabsf(y) > L->ceiling) {
185|         y = (y > 0.0f) ? L->ceiling : -L->ceiling;
186|         L->hard_clip++;
187|     }
188|     return y;
189| }
190| 
191| /*
192|  * [E] 真峰值前瞻限幅：float 域累加 + 1/sqrt(N) 预增益 + dBTP 驱动的限幅。
193|  *
194|  * 与 [5] mix_float_limiter 的差别只在窗口峰值检测：那里看采样点绝对值，
195|  * 这里看 4× 过采样后的样本间峰（重建峰），因此输出不但在采样点不越
196|  * ceiling，DAC sinc 重建后也不会越（欠读 ≤0.688 dB 已由 ceiling 的
197|  * −1 dBTP + 安全钳位双重余量覆盖）。返回安全钳位样本数。
198|  */
199| long mix_truepeak_limiter(const int16_t *a, const int16_t *b,
200|                           float *out, int n, void *ctx)
201| {
202|     truepeak_cfg_t *cfg = (truepeak_cfg_t *)ctx;
203|     tp_limiter_t L;
204|     float *tmp;
205|     long hard_clips;
206|     int i, total;
207| 
208|     cfg->active_samples = 0;
209|     cfg->hard_clips = 0;
210|     cfg->gain_sum = 0.0;
211|     cfg->gain_min = 1.0f;
212| 
213|     if (tp_limiter_init(&L, cfg->ceiling, cfg->look_ms,
214|                         cfg->atk_ms, cfg->rel_ms, cfg->fs) != 0) {
215|         memset(out, 0, (size_t)n * sizeof(float));
216|         return 0;
217|     }
218| 
219|     total = n + L.look;
220|     tmp = (float *)malloc((size_t)total * sizeof(float));
221|     if (!tmp) {
222|         tp_limiter_free(&L);
223|         memset(out, 0, (size_t)n * sizeof(float));
224|         return 0;
225|     }
226| 
227|     /* 末尾补 look 个零，把延迟线里剩余样本冲出（同 limiter.c） */
228|     for (i = 0; i < total; i++) {
229|         float s = (i < n)
230|                 ? (float)((int32_t)a[i] + (int32_t)b[i]) / 32768.0f
231|                 : 0.0f;
232|         tmp[i] = tp_limiter_step(&L, s * cfg->pregain);
233|     }
234| 
235|     /* 补偿 lookahead 延迟，使输出与其它算法样本对齐 */
236|     memcpy(out, tmp + L.look, (size_t)n * sizeof(float));
237| 
238|     hard_clips = L.hard_clip;
239|     cfg->active_samples = L.active;
240|     cfg->hard_clips = L.hard_clip;
241|     cfg->gain_sum = L.gain_sum / (double)total;
242|     cfg->gain_min = L.gain_min;
243|     free(tmp);
244|     tp_limiter_free(&L);
245|     return hard_clips;
246| }

