  1| /*
  2|  * comp_soft.c — 软拐点压缩器（feedforward soft-knee compressor）
  3|  *
  4|  * 出处：D. Giannoulis, M. Massberg, J. D. Reiss, "Digital Dynamic Range
  5|  * Compressor Design—A Tutorial and Analysis", J. Audio Eng. Soc. 60(6),
  6|  * 2012 June, pp. 399–408。逐条对应：
  7|  *
  8|  *   增益计算机（§2.2 Eq (4)，软拐点三分支抛物线）：
  9|  *     yG = xG                                     2(xG - T) <  -W
 10|  *     yG = xG + (1/R - 1)·(xG - T + W/2)^2 / (2W) |xG - T| <= W/2
 11|  *     yG = T + (xG - T)/R                         2(xG - T) >   W
 12|  *     W=0 时退化为硬拐点 Eq (3)。各分支均满足 yG <= xG，故 cdB = yG - xG
 13|  *     <= 0，增益只衰减不放大。
 14|  *
 15|  *   检测器（§2.3.3 Eq (15)，branching peak detector）：
 16|  *     yL[n] = αA·yL[n-1] + (1-αA)·xL[n]    xL[n] >  yL[n-1]  （起控支路）
 17|  *     yL[n] = αR·yL[n-1]                   xL[n] <= yL[n-1]  （释放支路）
 18|  *     释放支路只对状态放电，保证实测释放时间 = τR（Eq (16) 才是带
 19|  *     (1-αR)·xL[n] 项的变体，此处不用）。
 20|  *
 21|  *   域：xL = |x[n]|，检测器在线性域、dB 变换之前（论文 §2.4.1 Eq (20)
 22|  *   推荐位置）；随后 xG = 20·log10(yL)，cdB = yG - xG。
 23|  *
 24|  *   α 系数（§2.3 Eq (5)(7)）：一阶滤波 s[n] = α·s[n-1] + (1-α)·r[n]，
 25|  *   α = exp(-1/(tau·fs))。
 26|  *
 27|  * 结构（学 limiter.c 的状态藏 ctx 模式）：
 28|  *   累加 float 域 -> pregain -> 分支峰值检测（线性域）-> dB 变换 ->
 29|  *   软拐点增益计算机 -> 线性域增益 -> 乘回样本。T 直接定义在叠加信号的
 30|  *   dBFS 上，无任何检测域缩放。
 31|  *
 32|  * 无前瞻：限幅器需要 lookahead 是因为等检测到过载再降增益，峰已经
 33|  * 过去了；压缩器的起控平滑本身就是设计目标（Eq (15) 起控支路即平滑
 34|  * 器，10 ms 起控使增益在峰附近渐入），瞬态残余由末尾的安全钳位兜底
 35|  * （统计在 hard_clips）。因此本链路无延迟线，输出与其它算法样本对齐。
 36|  */
 37| 
 38| #include <string.h>
 39| #include <stdint.h>
 40| #include <math.h>
 41| 
 42| #include "comp_soft.h"
 43| 
 44| typedef struct {
 45|     float threshold_db;
 46|     float ratio;
 47|     float knee_db;
 48|     float alpha_a;      /* 起控支路系数，αA = exp(-1/(τA·fs)) */
 49|     float alpha_r;      /* 释放支路系数，αR = exp(-1/(τR·fs)) */
 50|     float env;          /* 检测器状态 yL[n-1]（线性域） */
 51|     long  active;
 52|     long  hard_clip;
 53|     double gain_sum;
 54|     float gain_min;
 55| } comp_soft_t;
 56| 
 57| static void comp_soft_init(comp_soft_t *C, const comp_soft_cfg_t *cfg)
 58| {
 59|     memset(C, 0, sizeof(*C));
 60|     C->threshold_db = cfg->threshold_db;
 61|     C->ratio        = cfg->ratio;
 62|     C->knee_db      = cfg->knee_db;
 63| 
 64|     C->alpha_a = expf(-1.0f / (cfg->atk_ms * 0.001f * (float)cfg->fs));
 65|     C->alpha_r = expf(-1.0f / (cfg->rel_ms * 0.001f * (float)cfg->fs));
 66| 
 67|     C->env      = 0.0f;
 68|     C->gain_min = 1.0f;
 69| }
 70| 
 71| /* 软拐点增益计算机 Eq (4)：输入检测电平 xG（dB），返回增益量（dB，<= 0） */
 72| static float soft_knee_gain_db(const comp_soft_t *C, float xg)
 73| {
 74|     float over = 2.0f * (xg - C->threshold_db);   /* 2(xG - T) */
 75|     float z;
 76| 
 77|     if (C->knee_db > 0.0f) {
 78|         if (over < -C->knee_db) {
 79|             return 0.0f;                          /* 低于拐点：单位增益 */
 80|         }
 81|         if (over <= C->knee_db) {
 82|             z = xg - C->threshold_db + C->knee_db * 0.5f;
 83|             return (1.0f / C->ratio - 1.0f) * z * z / (2.0f * C->knee_db);
 84|         }
 85|     } else if (xg <= C->threshold_db) {           /* W=0：硬拐点 */
 86|         return 0.0f;
 87|     }
 88|     /* 过拐点区 / 硬拐点过阈值：cdB = (T - xG)(1 - 1/R) */
 89|     return (C->threshold_db - xg) * (1.0f - 1.0f / C->ratio);
 90| }
 91| 
 92| /*
 93|  * [7] 软拐点压缩器：float 累加 + 分支峰值检测 + 软拐点增益计算机。
 94|  *
 95|  * 与 float+前瞻限幅的分工：限幅器保护峰值（硬拐点、快速、前瞻）；
 96|  * 压缩器调动态（软拐点、慢起释、无前瞻）。两者同属动态链路，可在
 97|  * 仓库的慢变增益剥离残差指标下公平对照。
 98|  */
 99| long mix_soft_knee(const int16_t *a, const int16_t *b,
100|                    float *out, int n, void *ctx)
101| {
102|     comp_soft_cfg_t *cfg = (comp_soft_cfg_t *)ctx;
103|     comp_soft_t C;
104|     int i;
105| 
106|     cfg->active_samples = 0;
107|     cfg->hard_clips = 0;
108|     cfg->gain_sum = 0.0;
109|     cfg->gain_min = 1.0f;
110| 
111|     comp_soft_init(&C, cfg);
112| 
113|     for (i = 0; i < n; i++) {
114|         float x, xl, xg, g_db, g, y;
115| 
116|         x = (float)((int32_t)a[i] + (int32_t)b[i]) / 32768.0f * cfg->pregain;
117| 
118|         /* 检测：线性域分支峰值检测器 Eq (15) */
119|         xl = fabsf(x);
120|         if (xl < 1e-9f) xl = 1e-9f;               /* 静音期 log10 的下限保护 */
121|         if (xl > C.env) {
122|             C.env = C.alpha_a * C.env + (1.0f - C.alpha_a) * xl;
123|         } else {
124|             C.env = C.alpha_r * C.env;
125|         }
126| 
127|         /* 增益计算机 Eq (4)：xG = 20·log10(yL)，cdB = yG - xG */
128|         xg = 20.0f * log10f(C.env);
129|         g_db = soft_knee_gain_db(&C, xg);
130|         if (g_db > 0.0f) g_db = 0.0f;             /* 只衰减不放大（门槛条款） */
131|         g = powf(10.0f, g_db * 0.05f);
132| 
133|         y = x * g;
134|         if (y > 1.0f)  { y = 1.0f;  C.hard_clip++; }
135|         if (y < -1.0f) { y = -1.0f; C.hard_clip++; }
136|         out[i] = y;
137| 
138|         if (g < 0.999f) C.active++;
139|         C.gain_sum += (double)g;
140|         if (g < C.gain_min) C.gain_min = g;
141|     }
142| 
143|     cfg->active_samples = C.active;
144|     cfg->hard_clips = C.hard_clip;
145|     cfg->gain_sum = C.gain_sum / (double)n;
146|     cfg->gain_min = C.gain_min;
147|     return C.hard_clip;
148| }

